import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { Activity, ArrowDownRight, ArrowUpRight, BarChart3, Bell, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, Code2, Copy, CreditCard, ExternalLink, FileCode2, Filter, Globe2, Handshake, Inbox as InboxIcon, LayoutDashboard, Link2, ListFilter, LogOut, MapPin, Megaphone, Menu, MessageCircle, MousePointer2, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Users, UsersRound, Wallet, Webhook, X } from "lucide-react";
import { Badge } from "./components/ui/badge";
import { Button } from "./components/ui/button";
import { Card } from "./components/ui/card";
import { Input } from "./components/ui/input";
import { Select } from "./components/ui/select";
import { api, date, money } from "./lib/utils";

type Workspace = { id: string; name: string; public_key: string; currency: string };
type Lead = { id: string; name: string; phone: string | null; email: string | null; status: string; value: number; source: string; campaign: string | null; landing_page: string | null; first_seen: string; follow_up_at: string | null; follow_up_note: string | null };
type Summary = { leads: number; closing: number; revenue: number; spend: number; roas: number | null; events: number; stages: Array<{ status: string; count: number }>; sources: Array<{ source: string; count: number }> };
type Platform = "Meta" | "Google Ads" | "TikTok" | "GA4" | "LinkedIn" | "ChatGPT Ads";
const platformList: Platform[] = ["Meta", "Google Ads", "TikTok", "GA4", "LinkedIn", "ChatGPT Ads"];
const trackingEvents = ["Visit LP", "Click CTA", "Masuk WA", "MQL", "Prospek", "Closing", "Isi Form"];
const stages = ["Masuk WA", "MQL", "Prospek", "Closing", "Lost"];
const navGroups = [
  { label: "Workspace", collapsible: false, items: [{ title: "Ringkasan", path: "/", icon: LayoutDashboard }, { title: "Inbox", path: "/inbox", icon: InboxIcon }, { title: "Leads", path: "/leads", icon: Users }, { title: "Campaign report", path: "/reports/campaign", icon: BarChart3 }, { title: "Lokasi leads", path: "/leads/locations", icon: MapPin }] },
  { label: "WhatsApp", collapsible: true, icon: MessageCircle, items: [{ title: "Sessions", path: "/whatsapp/sessions", icon: MessageCircle }, { title: "WA Rotator", path: "/whatsapp/rotator", icon: Activity }, { title: "Rules", path: "/whatsapp/rules", icon: SlidersHorizontal }, { title: "Balas cepat", path: "/whatsapp/quick-replies", icon: MessageCircle }, { title: "Template", path: "/whatsapp/templates", icon: FileCode2 }, { title: "Broadcast", path: "/whatsapp/broadcast", icon: Megaphone }, { title: "Form & katalog", path: "/whatsapp/form-katalog", icon: FileCode2 }, { title: "Biaya WhatsApp", path: "/whatsapp/biaya", icon: Wallet }] },
  { label: "Tracking", collapsible: true, icon: Activity, items: [{ title: "Integrasi iklan", path: "/tracking/ads", icon: Link2 }, { title: "Custom domain", path: "/tracking/domains", icon: Globe2 }, { title: "Landing page", path: "/tracking/landing-page", icon: FileCode2 }, { title: "Sumber lead", path: "/tracking/sumber-lead", icon: UsersRound }, { title: "Custom audience", path: "/tracking/audiens", icon: UsersRound }, { title: "Riset iklan", path: "/tracking/ad-research", icon: Search }, { title: "Event logs", path: "/event-logs", icon: Activity }] },
  { label: "Pengaturan", collapsible: true, icon: Settings2, items: [{ title: "Workspace", path: "/settings/workspace", icon: LayoutDashboard }, { title: "Team", path: "/settings/team", icon: Users }, { title: "Billing", path: "/settings/billing", icon: Wallet }, { title: "Afiliasi", path: "/settings/affiliate", icon: Handshake }, { title: "API & Webhook", path: "/settings/api-webhook", icon: Webhook }] },
];
const defaultMappings: Record<string, string> = { "Visit LP": "PageView", "Click CTA": "Lead", "Masuk WA": "Contact", MQL: "QualifiedLead", Prospek: "Lead", Closing: "Purchase", "Isi Form": "SubmitApplication" };

export default function App() {
  const [workspace, setWorkspace] = useState<Workspace | null>(null);
  const [loading, setLoading] = useState(true);
  const [route, setRoute] = useState(window.location.pathname);
  const [menuOpen, setMenuOpen] = useState(false);
  const [expandedNav, setExpandedNav] = useState<Record<string, boolean>>({});
  const [notice, setNotice] = useState("");
  const [authMode, setAuthMode] = useState<"login" | "register" | "forgot" | "reset">(window.location.pathname === "/reset-password" ? "reset" : "login");
  const [authError, setAuthError] = useState("");

  const loadWorkspace = useCallback(async () => {
    try { const result = await api<{ workspace: Workspace }>("/api/me"); setWorkspace(result.workspace); }
    catch { setWorkspace(null); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void loadWorkspace(); }, [loadWorkspace]);
  useEffect(() => { const onPop = () => setRoute(window.location.pathname); window.addEventListener("popstate", onPop); return () => window.removeEventListener("popstate", onPop); }, []);
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(""), 3600); return () => window.clearTimeout(timer); }, [notice]);
  const go = (path: string) => { history.pushState({}, "", path); setRoute(path); setMenuOpen(false); };
  const logout = async () => { await api("/api/auth/logout", { method: "POST" }); setWorkspace(null); };

  if (loading) return <div className="loading-screen"><div className="loader-mark">a</div><span>Menyiapkan workspace</span></div>;
  if (!workspace || authMode === "reset") return <AuthScreen mode={authMode} setMode={setAuthMode} error={authError} setError={setAuthError} onSuccess={loadWorkspace} onResetDone={() => { history.replaceState({}, "", "/"); setRoute("/"); setWorkspace(null); setAuthError("Kata sandi berhasil diperbarui. Silakan masuk."); setAuthMode("login"); }} />;

  const currentNav = navGroups.flatMap(group => group.items).find(item => item.path === route) ?? navGroups.flatMap(group => group.items).find(item => item.path !== "/" && route.startsWith(`${item.path}/`));
  const section = currentNav?.title ?? (route === "/" ? "Ringkasan" : "Workspace");
  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? "sidebar-open" : ""}`}>
      <div className="brand"><div className="brand-mark">a</div><div><div className="brand-name">arenka<span>ads</span></div><div className="brand-caption">ATTRIBUTION WORKSPACE</div></div><button className="mobile-close icon-button" aria-label="Tutup menu" onClick={() => setMenuOpen(false)}><X size={18}/></button></div>
      <button className="workspace-picker" onClick={() => setNotice("Workspace aktif: " + workspace.name)}><span className="workspace-avatar">{workspace.name.slice(0,1).toUpperCase()}</span><span className="workspace-meta"><b>{workspace.name}</b><small>Workspace</small></span><ChevronDown size={15}/></button>
      <div className="side-nav">{navGroups.map(group => { const active = group.items.some(item => item.path === route || (item.path !== "/" && route.startsWith(`${item.path}/`))); const open = !group.collapsible || Boolean(expandedNav[group.label]) || active; const GroupIcon = group.icon; return <div className="nav-group" key={group.label}>{group.collapsible ? <button className={`nav-group-toggle ${active ? "group-active" : ""}`} aria-expanded={open} onClick={() => setExpandedNav(v => ({ ...v, [group.label]: !open }))}>{GroupIcon && <GroupIcon size={17} strokeWidth={1.8}/>}<span>{group.label}</span><ChevronRight className={open ? "nav-chevron nav-chevron-open" : "nav-chevron"} size={15}/></button> : <div className="nav-label">{group.label}</div>}{open && <div className={group.collapsible ? "nav-subitems" : ""}>{group.items.map(item => <button key={item.path} className={`nav-item ${route === item.path || (item.path !== "/" && route.startsWith(`${item.path}/`)) ? "active" : ""}`} aria-current={route === item.path ? "page" : undefined} onClick={() => go(item.path)}><item.icon size={17} strokeWidth={1.8}/><span>{item.title}</span></button>)}</div>}</div> })}</div>
      <div className="sidebar-bottom"><button className="nav-item support-link" onClick={() => setNotice("Hubungi tim Arenka untuk bantuan workspace dan integrasi.")}><CircleHelp size={17}/><span>Bantuan</span></button><div className="plan-note"><div className="plan-note-icon"><ShieldCheck size={16}/></div><div><b>Tracking berjalan</b><span>Workspace siap menerima event</span></div></div><button className="account-row" onClick={() => void logout()}><div className="account-avatar">{workspace.name.slice(0,1).toUpperCase()}</div><div className="account-info"><b>{workspace.name}</b><small>Keluar dari akun</small></div><LogOut size={16}/></button></div>
    </aside>
    {menuOpen && <button aria-label="Tutup navigasi" className="mobile-scrim" onClick={() => setMenuOpen(false)} />}
    <main className="main-shell">
      <header className="topbar"><div className="crumb"><button className="mobile-menu icon-button" aria-label="Buka menu" onClick={() => setMenuOpen(true)}><Menu size={20}/></button><span>Workspace</span><span className="crumb-separator">/</span><b>{section}</b></div><div className="top-actions"><span className="live-indicator"><i/> Workspace aktif</span><button className="icon-button" aria-label="Bantuan" onClick={() => setNotice("Pasang script tracking di situs, lalu event akan muncul di sini.")}><CircleHelp size={18}/></button><button className="icon-button notification-button" aria-label="Notifikasi"><Bell size={18}/></button><div className="top-avatar">{workspace.name.slice(0,1).toUpperCase()}</div></div></header>
      <div className="page-content">
        {route === "/leads" ? <LeadsPage notify={setNotice}/> : route === "/leads/locations" ? <LeadLocationsPage notify={setNotice}/> : route === "/tracking/ads" ? <IntegrationsPage workspace={workspace} notify={setNotice}/> : route === "/reports/campaign" ? <ReportPage notify={setNotice}/> : route === "/event-logs" ? <EventsPage/> : route === "/" ? <DashboardPage workspace={workspace} go={go} notify={setNotice}/> : <PlannedModule title={section} go={go}/>}
      </div>
    </main>
    {notice && <div role="status" className="toast"><span className="toast-check"><Check size={14}/></span>{notice}<button aria-label="Tutup" onClick={() => setNotice("")}><X size={15}/></button></div>}
  </div>;
}

function AuthScreen({ mode, setMode, error, setError, onSuccess, onResetDone }: { mode: "login" | "register" | "forgot" | "reset"; setMode: (m: "login" | "register" | "forgot" | "reset") => void; error: string; setError: (e: string) => void; onSuccess: () => Promise<void>; onResetDone: () => void }) {
  const [busy, setBusy] = useState(false), [sent, setSent] = useState(false);
  const titles = { login: "Masuk ke akun", register: "Buat akun", forgot: "Atur ulang kata sandi", reset: "Buat kata sandi baru" };
  const descriptions = { login: "Masuk untuk melihat data tracking Anda.", register: "Buat workspace untuk mulai mengukur sumber lead.", forgot: "Masukkan email akun Anda. Jika terdaftar, kami kirim tautan pemulihan.", reset: "Gunakan kata sandi baru minimal 12 karakter." };
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setError(""); setSent(false); setBusy(true);
    const data = new FormData(event.currentTarget);
    try {
      if (mode === "forgot") { await api("/api/auth/forgot-password", { method: "POST", body: JSON.stringify({ email: data.get("email") }) }); setSent(true); return; }
      if (mode === "reset") { const token = new URLSearchParams(location.search).get("token") ?? ""; await api("/api/auth/reset-password", { method: "POST", body: JSON.stringify({ token, password: data.get("password") }) }); onResetDone(); return; }
      await api(`/api/auth/${mode === "register" ? "register" : "login"}`, { method: "POST", body: JSON.stringify({ email: data.get("email"), password: data.get("password"), workspace: data.get("workspace") }) }); await onSuccess();
    } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  };
  return <div className="auth-layout"><div className="auth-aside"><div className="brand auth-brand"><div className="brand-mark">a</div><div><div className="brand-name">arenka<span>ads</span></div><div className="brand-caption">ATTRIBUTION WORKSPACE</div></div></div><div className="auth-story"><span className="eyebrow">SIGNAL OVER NOISE</span><h1>Hubungkan klik<br/>dengan <em>konversi.</em></h1><p>Satukan event, sumber lead, dan performa iklan dalam satu alur yang bisa ditelusuri.</p><div className="story-line"><span/><span/><span/><span/><span/><span/><span/><span/></div><div className="story-caption"><Activity size={15}/> Pelacakan event lintas kanal</div></div><div className="auth-footer">ARENKA ADS TRACKER <span>·</span> PRIVATE WORKSPACE</div></div><div className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><span className="eyebrow">{mode === "register" ? "MULAI WORKSPACE" : mode === "reset" || mode === "forgot" ? "PEMULIHAN AKUN" : "SELAMAT DATANG KEMBALI"}</span><h2>{titles[mode]}</h2><p>{descriptions[mode]}</p>{mode === "register" && <label>Nama workspace<Input name="workspace" required maxLength={80} placeholder="Contoh: Arenka Marketing" autoComplete="organization"/></label>}{mode !== "reset" && <label>Email<Input type="email" name="email" required maxLength={160} placeholder="nama@perusahaan.com" autoComplete="email"/></label>}{(mode === "login" || mode === "register" || mode === "reset") && <label>Kata sandi<Input type="password" name="password" required minLength={mode === "login" ? 1 : 12} maxLength={128} placeholder={mode === "login" ? "Masukkan kata sandi" : "Minimal 12 karakter"} autoComplete={mode === "login" ? "current-password" : "new-password"}/></label>}{mode === "login" && <button className="auth-link" type="button" onClick={() => { setError(""); setMode("forgot"); }}>Lupa kata sandi?</button>}{error && <div className="form-error" role="alert">{error}</div>}{sent && <div className="form-success" role="status">Jika email terdaftar, tautan pengaturan kata sandi akan dikirim. Periksa inbox Anda.</div>}{mode === "reset" && !new URLSearchParams(location.search).get("token") && <div className="form-error" role="alert">Tautan tidak valid atau sudah kedaluwarsa. Minta tautan pemulihan baru.</div>}<Button className="auth-submit" disabled={busy || (mode === "reset" && !new URLSearchParams(location.search).get("token"))}>{busy ? "Memproses…" : mode === "register" ? "Buat workspace" : mode === "forgot" ? "Kirim tautan pemulihan" : mode === "reset" ? "Simpan kata sandi baru" : "Masuk"}</Button><div className="auth-switch">{mode === "register" ? "Sudah punya akun?" : mode === "login" ? "Belum punya akun?" : "Ingin kembali?"}<button type="button" onClick={() => {setError("");setSent(false);setMode(mode === "register" ? "login" : mode === "login" ? "register" : "login");}}>{mode === "register" || mode === "forgot" || mode === "reset" ? "Masuk" : "Daftar sekarang"}</button></div><div className="auth-security"><ShieldCheck size={15}/> Kata sandi dilindungi hash PBKDF2 · sesi privat</div></form></div></div>;
}

function PageHeading({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: ReactNode }) {
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{actions && <div className="heading-actions">{actions}</div>}</div>;
}
function Metric({ label, value, note, icon: Icon, delta }: { label: string; value: string; note: string; icon: typeof Users; delta?: string }) {
  return <Card className="metric-card"><div className="metric-top"><span>{label}</span><span className="metric-icon"><Icon size={17}/></span></div><div className="metric-value">{value}</div><div className="metric-note">{delta ? <span className="delta"><ArrowUpRight size={13}/>{delta}</span> : null}{note}</div></Card>;
}
function DashboardPage({ workspace, go, notify }: { workspace: Workspace; go: (p: string) => void; notify: (s: string) => void }) {
  const [summary, setSummary] = useState<Summary | null>(null);
  useEffect(() => { void api<Summary>("/api/summary").then(setSummary).catch(e => notify(e.message)); }, [notify]);
  const max = Math.max(1, ...((summary?.sources ?? []).map(s => s.count)));
  return <><PageHeading eyebrow="OVERVIEW / 30 HARI TERAKHIR" title="Ringkasan performa" description={`Pantau perjalanan lead dari klik pertama di ${workspace.name}.`} actions={<><Button variant="secondary" onClick={() => go("/tracking/ads")}><Link2 size={16}/> Hubungkan platform</Button><Button onClick={() => go("/leads")}><Plus size={16}/> Tambah lead</Button></>}/><div className="metrics-grid"><Metric label="Total leads" value={String(summary?.leads ?? 0)} note="Semua sumber" icon={Users}/><Metric label="Ad spend" value={money(summary?.spend ?? 0)} note="30 hari terakhir" icon={CreditCard}/><Metric label="Revenue closing" value={money(summary?.revenue ?? 0)} note={`${summary?.closing ?? 0} lead closing`} icon={ArrowUpRight}/><Metric label="ROAS workspace" value={summary?.roas == null ? "—" : `${summary.roas.toFixed(2)}×`} note="Revenue / ad spend" icon={BarChart3}/></div><div className="overview-grid"><Card className="panel source-panel"><div className="panel-heading"><div><h2>Sumber lead</h2><p>Distribusi lead berdasarkan kanal pertama</p></div><button className="text-action" onClick={() => go("/reports/campaign")}>Lihat laporan <ArrowUpRight size={14}/></button></div>{summary?.sources?.length ? <div className="source-list">{summary.sources.map((s,i)=><div className="source-row" key={s.source}><div className="source-name"><span className={`source-dot dot-${i%5}`}/>{s.source}<b>{s.count}</b></div><div className="source-track"><span style={{width:`${Math.max(4,s.count/max*100)}%`}}/></div></div>)}</div> : <Empty icon={<MousePointer2 size={19}/>} title="Belum ada sumber lead" text="Pasang tracking code di website untuk mulai melihat atribusi." action={<Button size="sm" onClick={() => go("/tracking/ads")}>Buka tracking code</Button>}/>}</Card><Card className="panel stage-panel"><div className="panel-heading"><div><h2>Perjalanan lead</h2><p>Lead yang bergerak ke tahap berikutnya</p></div><span className="panel-period">30 HARI</span></div><div className="funnel-list">{stages.map((stage,i)=>{const count=summary?.stages?.find(s=>s.status===stage)?.count??0;return <div className="funnel-row" key={stage}><span className="funnel-index">0{i+1}</span><span className="funnel-name">{stage}</span><div className="funnel-meter"><i style={{width:`${Math.max(count?8:0,(summary?.leads?count/summary.leads*100:0))}%`}}/></div><b>{count}</b></div>})}</div><button className="panel-link" onClick={()=>go("/leads")}>Kelola leads <ArrowUpRight size={14}/></button></Card></div><Card className="setup-banner"><div className="setup-symbol"><Code2 size={21}/></div><div className="setup-copy"><span className="eyebrow">LANGKAH BERIKUTNYA</span><h2>Hubungkan titik sentuh iklan Anda</h2><p>Pasang satu script untuk mulai menerima kunjungan dan interaksi dari landing page.</p></div><div className="setup-actions"><Badge className="status-badge"><i/> Tracker {summary?.events ? "menerima event" : "siap dipasang"}</Badge><Button variant="secondary" onClick={()=>go("/tracking/ads")}>Lihat instruksi <ArrowUpRight size={15}/></Button></div></Card></>;
}

function Empty({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{action}</div>; }
function LeadsPage({ notify }: { notify: (s:string)=>void }) {
  const [leads,setLeads]=useState<Lead[]>([]),[query,setQuery]=useState(""),[status,setStatus]=useState("Semua status"),[followupFilter,setFollowupFilter]=useState(""),[modal,setModal]=useState(false),[followupLead,setFollowupLead]=useState<Lead|null>(null),[busy,setBusy]=useState(false);
  const reload=useCallback(async()=>{try{setLeads(await api<Lead[]>(`/api/leads?q=${encodeURIComponent(query)}${status!=="Semua status"?`&status=${encodeURIComponent(status)}`:""}${followupFilter?`&follow_up=${encodeURIComponent(followupFilter)}`:""}`))}catch(e){notify((e as Error).message)}},[query,status,followupFilter,notify]);
  useEffect(()=>{void reload()},[reload]);
  const add=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const fd=new FormData(e.currentTarget);try{await api("/api/leads",{method:"POST",body:JSON.stringify(Object.fromEntries(fd))});setModal(false);notify("Lead berhasil ditambahkan.");await reload()}catch(err){notify((err as Error).message)}finally{setBusy(false)}};
  const changeStatus=async(id:string,next:string)=>{try{await api(`/api/leads/${id}`,{method:"PATCH",body:JSON.stringify({status:next})});await reload()}catch(e){notify((e as Error).message)}};
  const saveFollowUp=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!followupLead)return;setBusy(true);const fd=new FormData(e.currentTarget);try{await api(`/api/leads/${followupLead.id}`,{method:"PATCH",body:JSON.stringify({follow_up_at:fd.get("follow_up_at")||null,follow_up_note:fd.get("follow_up_note")})});setFollowupLead(null);notify("Tindak lanjut lead disimpan.");await reload()}catch(err){notify((err as Error).message)}finally{setBusy(false)}};
  const exportCsv=()=>{const rows=[["Nama","Telepon","Email","Status","Nilai","Sumber","Campaign","Tanggal","Follow-up","Catatan follow-up"],...leads.map(l=>[l.name,l.phone??"",l.email??"",l.status,String(l.value),l.source,l.campaign??"",l.first_seen,l.follow_up_at??"",l.follow_up_note??""])];const csv=rows.map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(",")).join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"}));a.download="arenka-leads.csv";a.click();URL.revokeObjectURL(a.href)};
  return <><PageHeading eyebrow="WORKSPACE / LEADS" title="Daftar leads" description="Lihat dan kelola setiap lead dari kunjungan pertama sampai closing." actions={<><Button variant="secondary" onClick={exportCsv}><ArrowDownRight size={16}/> Ekspor CSV</Button><Button onClick={()=>setModal(true)}><Plus size={16}/> Tambah lead</Button></>}/><Card className="table-panel"><div className="table-toolbar"><div className="search-wrap"><Search size={16}/><Input aria-label="Cari leads" placeholder="Cari nama, nomor, atau email" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="toolbar-filters"><ListFilter size={16}/><Select aria-label="Filter status" value={status} onChange={e=>setStatus(e.target.value)}><option>Semua status</option>{stages.map(s=><option key={s}>{s}</option>)}</Select></div><div className="toolbar-filters"><CalendarDays size={16}/><Select aria-label="Filter follow-up" value={followupFilter} onChange={e=>setFollowupFilter(e.target.value)}><option value="">Semua follow-up</option><option value="today">Hari ini</option><option value="overdue">Terlambat</option><option value="upcoming">Mendatang</option></Select></div><span className="row-count">{leads.length} leads</span></div>{leads.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>Lead</th><th>Status</th><th>Sumber / campaign</th><th>Nilai</th><th>Masuk</th><th>Follow-up</th></tr></thead><tbody>{leads.map(l=><tr key={l.id}><td><div className="lead-cell"><div className="lead-initial">{l.name.slice(0,1).toUpperCase()}</div><div><b>{l.name}</b><small>{l.phone||l.email||"Kontak belum tersedia"}</small></div></div></td><td><Select aria-label={`Status ${l.name}`} className={`status-select status-${l.status.toLowerCase().replaceAll(" ","-")}`} value={l.status} onChange={e=>void changeStatus(l.id,e.target.value)}>{stages.map(s=><option key={s}>{s}</option>)}</Select></td><td><div className="campaign-cell"><b>{l.source}</b><small>{l.campaign||"Tanpa campaign"}</small></div></td><td className="mono-value">{l.value?money(l.value):"—"}</td><td className="date-value">{date(l.first_seen)}</td><td><Button size="sm" variant="secondary" onClick={()=>setFollowupLead(l)}><CalendarDays size={13}/>{l.follow_up_at?date(l.follow_up_at):"Atur"}</Button></td></tr>)}</tbody></table></div>:<Empty icon={<Users size={19}/>} title="Belum ada lead" text="Tambahkan lead secara manual atau pasang tracking code agar data masuk otomatis." action={<Button size="sm" onClick={()=>setModal(true)}><Plus size={14}/> Tambah lead</Button>}/>}<div className="table-footer"><span>Menampilkan {leads.length} lead</span><span>Maksimal 200 hasil</span></div></Card>{modal&&<Dialog title="Tambah lead" onClose={()=>setModal(false)}><form className="dialog-form" onSubmit={add}><label>Nama lead<Input name="name" required placeholder="Nama kontak" maxLength={120}/></label><div className="form-row"><label>Nomor WhatsApp<Input name="phone" placeholder="+62 812…" maxLength={40}/></label><label>Email<Input type="email" name="email" placeholder="nama@email.com" maxLength={160}/></label></div><div className="form-row"><label>Status<Select name="status" defaultValue="Masuk WA">{stages.map(s=><option key={s}>{s}</option>)}</Select></label><label>Nilai closing (IDR)<Input name="value" type="number" min="0" step="1000" defaultValue="0"/></label></div><div className="form-row"><label>Sumber<Input name="source" defaultValue="Manual" maxLength={80}/></label><label>Campaign<Input name="campaign" placeholder="Nama campaign" maxLength={160}/></label></div><div className="dialog-actions"><Button type="button" variant="secondary" onClick={()=>setModal(false)}>Batal</Button><Button disabled={busy}>{busy?"Menyimpan…":"Simpan lead"}</Button></div></form></Dialog>}{followupLead&&<Dialog title={`Tindak lanjut · ${followupLead.name}`} onClose={()=>setFollowupLead(null)}><form className="dialog-form" onSubmit={saveFollowUp}><label>Tanggal follow-up<Input name="follow_up_at" type="date" defaultValue={followupLead.follow_up_at??""}/><small>Kosongkan tanggal untuk menghapus jadwal.</small></label><label>Catatan<Input name="follow_up_note" defaultValue={followupLead.follow_up_note??""} placeholder="Contoh: hubungi kembali setelah demo" maxLength={500}/></label><div className="dialog-actions"><Button type="button" variant="secondary" onClick={()=>setFollowupLead(null)}>Batal</Button><Button disabled={busy}>{busy?"Menyimpan…":"Simpan follow-up"}</Button></div></form></Dialog>}</>;
}

function Dialog({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div className="dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabIndex={-1} onKeyDown={e=>{if(e.key==="Escape")onClose()}}><div className="dialog-header"><div><span className="eyebrow">WORKSPACE</span><h2 id="dialog-title">{title}</h2></div><button className="icon-button" aria-label="Tutup dialog" onClick={onClose}><X size={18}/></button></div>{children}</section></div>; }

function IntegrationsPage({ workspace, notify }: { workspace: Workspace; notify:(s:string)=>void }) {
  const [tab,setTab]=useState("Platform"),[platform,setPlatform]=useState<Platform>("Meta"),[mappings,setMappings]=useState<Record<string,string>>({}),[integrations,setIntegrations]=useState<any[]>([]),[modal,setModal]=useState<Platform|null>(null),[busy,setBusy]=useState(false),[copy,setCopy]=useState(false),[accounts,setAccounts]=useState<Record<string,any>>({});
  useEffect(()=>{void Promise.all([api<any>("/api/mappings"),api<any>("/api/integrations")]).then(([m,i])=>{const mappingRows=m.mappings as Array<any>;setMappings(Object.fromEntries(trackingEvents.map(ev=>[ev,mappingRows.find((r:any)=>r.platform===platform&&r.event_name===ev)?.destination_event||""])));setIntegrations(i.integrations)}).catch(e=>notify(e.message))},[notify,platform]);
  const selectedIntegration=integrations.find(i=>i.platform===platform);
  const setCurrentPlatform=(p:Platform)=>{setPlatform(p);const next=integrations.find(i=>i.platform===p);setAccounts(next?{[p]:{account_id:next.account_id??"",account_name:next.account_name??""}}:accounts)};
  const script=`<!-- Arenka Ads Tracker -->\n<script async src="https://trackers.arenka.biz.id/tracker.js?k=${workspace.public_key}"></script>`;
  const copyText=async(value:string)=>{try{await navigator.clipboard.writeText(value);setCopy(true);window.setTimeout(()=>setCopy(false),1600);notify("Disalin ke clipboard.")}catch{notify("Clipboard tidak tersedia di browser ini.")}};
  const saveMappings=async()=>{setBusy(true);try{await api("/api/mappings",{method:"PUT",body:JSON.stringify({platform,mappings})});notify(`Pemetaan ${platform} tersimpan.`)}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
  const saveAccount=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!modal)return;setBusy(true);const fd=new FormData(e.currentTarget);try{await api(`/api/integrations/${encodeURIComponent(modal)}`,{method:"PUT",body:JSON.stringify(Object.fromEntries(fd))});const data=await api<any>("/api/integrations");setIntegrations(data.integrations);setModal(null);notify("Detail akun disimpan. Hubungan OAuth belum aktif.")}catch(err){notify((err as Error).message)}finally{setBusy(false)}};
  return <><PageHeading eyebrow="TRACKING / AD PLATFORMS" title="Integrasi iklan" description="Kelola platform, event yang dikirim, dan script tracking workspace." actions={<Button variant="secondary" onClick={()=>setTab("Platform")}><SlidersHorizontal size={16}/> Status platform</Button>}/><div className="section-tabs" role="tablist" aria-label="Pengaturan tracking">{["Platform","Event mapping","Tracking code","UTM"].map(t=><button key={t} role="tab" aria-selected={tab===t} className={tab===t?"selected":""} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==="Platform"?<div className="platform-grid">{platformList.map((p,i)=>{const record=integrations.find(x=>x.platform===p);const name=p==="Google Ads"?"Google Ads":p;return <Card className="platform-card" key={p}><div className="platform-card-top"><PlatformMark index={i} name={p}/><Badge className={record?.connected?"connected":"disconnected"}><i/>{record?.connected?"Terhubung":"Belum terhubung"}</Badge></div><h2>{name}</h2><p>{record?.account_name||platformDescription[p]}</p><div className="platform-card-footer">{record?.account_id&&<span className="account-number">ID {record.account_id}</span>}<Button variant="secondary" size="sm" onClick={()=>{setModal(p);setAccounts(s=>({...s,[p]:{account_id:record?.account_id??"",account_name:record?.account_name??""}}))}}>{record?.account_id?"Atur akun":"Hubungkan"}<ExternalLink size={14}/></Button></div></Card>})}</div>:tab==="Event mapping"?<Card className="mapping-panel"><div className="mapping-header"><div><h2>Mapping event</h2><p>Sesuaikan event yang diteruskan ke setiap platform.</p></div><Button variant="secondary" size="sm" onClick={()=>{setMappings(defaultMappings);notify("Mapping rekomendasi diterapkan. Simpan untuk menggunakan.")}}><Sparkles size={15}/> Pakai rekomendasi</Button></div><div className="platform-pills" role="tablist" aria-label="Pilih platform">{platformList.map(p=><button role="tab" aria-selected={platform===p} className={platform===p?"selected":""} key={p} onClick={()=>setCurrentPlatform(p)}>{p}</button>)}</div><div className="mapping-count">{Object.values(mappings).filter(Boolean).length} dari {trackingEvents.length} event dipetakan</div><div className="mapping-table"><div className="mapping-table-head"><span>Event Arenka</span><span>Event platform {platform}</span></div>{trackingEvents.map(ev=><div className="mapping-row" key={ev}><div className="event-label"><span className="event-indicator"/>{ev}</div><Select aria-label={`Pilih event ${platform} untuk ${ev}`} value={mappings[ev]||""} onChange={e=>setMappings(m=>({...m,[ev]:e.target.value}))}><option value="">Tidak dipetakan</option>{(platformOptions[platform]??[]).map(o=><option key={o}>{o}</option>)}</Select></div>)}</div><div className="mapping-actions"><span>Perubahan tersimpan per platform.</span><Button onClick={()=>void saveMappings()} disabled={busy}>{busy?"Menyimpan…":`Simpan ${platform}`}</Button></div></Card>:tab==="Tracking code"?<div className="tracker-layout"><Card className="tracker-instructions"><div className="panel-heading"><div><h2>Pasang tracking code</h2><p>Satu kali di website utama untuk merekam interaksi.</p></div><Badge className="code-status"><i/> Siap dipasang</Badge></div><div className="steps">{[{n:"01",title:"Salin script",detail:"Kode workspace unik sudah termasuk di bawah."},{n:"02",title:"Tempel di website",detail:"Letakkan sebelum tag penutup </head>. Pasang sekali per domain."},{n:"03",title:"Periksa event",detail:"Buka landing page dan lihat event pertama masuk di Event logs."}].map(s=><div className="instruction-step" key={s.n}><span>{s.n}</span><div><b>{s.title}</b><p>{s.detail}</p></div></div>)}</div><div className="install-note"><ShieldCheck size={17}/><span>Script merekam page view, UTM, dan klik CTA WhatsApp secara otomatis.</span></div><button className="event-logs-link" onClick={()=>{history.pushState({},"","/event-logs");window.dispatchEvent(new PopStateEvent("popstate"))}}>Buka event logs <ArrowUpRight size={14}/></button></Card><Card className="code-panel"><div className="code-head"><div><span className="eyebrow">INSTALLATION SNIPPET</span><b>Script Arenka</b></div><Button size="sm" onClick={()=>void copyText(script)}><Copy size={14}/>{copy?"Tersalin":"Salin kode"}</Button></div><pre><code>{script}</code></pre><div className="code-foot"><span>Workspace key</span><code>{workspace.public_key}</code></div></Card></div>:<UtmPage notify={notify}/>}{modal&&<Dialog title={`Hubungkan ${modal}`} onClose={()=>setModal(null)}><form className="dialog-form" onSubmit={saveAccount}><div className="oauth-note"><ShieldCheck size={17}/><span>Integrasi OAuth untuk mengambil data iklan belum dikonfigurasi. Anda bisa menyimpan ID akun untuk pencocokan report.</span></div><label>Nama akun (opsional)<Input name="account_name" defaultValue={accounts[modal]?.account_name||""} placeholder="Arenka Official" maxLength={120}/></label><label>ID akun iklan<Input name="account_id" defaultValue={accounts[modal]?.account_id||""} placeholder="Masukkan ID akun" maxLength={100}/><small>Tidak menyimpan access token atau kredensial platform.</small></label><div className="dialog-actions"><Button type="button" variant="secondary" onClick={()=>setModal(null)}>Batal</Button><Button disabled={busy}>{busy?"Menyimpan…":"Simpan detail"}</Button></div></form></Dialog>}</>;
}
const platformDescription:Record<string,string>={"Meta":"Facebook dan Instagram Ads","Google Ads":"Search, display, dan video campaign","TikTok":"TikTok Ads Manager","GA4":"Google Analytics 4","LinkedIn":"LinkedIn Campaign Manager","ChatGPT Ads":"OpenAI Ads"};
const platformOptions:Record<string,string[]>={Meta:["PageView","ViewContent","Lead","Contact","CompleteRegistration","SubmitApplication","Purchase"],"Google Ads":["page_view","click","generate_lead","qualify_lead","close_convert_lead","purchase"],TikTok:["PageView","ClickButton","Contact","SubmitForm","CompletePayment"],GA4:["page_view","click","generate_lead","qualify_lead","purchase"],LinkedIn:["PageView","Lead","QualifiedLead","Purchase"],"ChatGPT Ads":["PageView","Lead","Contact","Purchase"]};
function PlatformMark({index,name}:{index:number;name:string}){return <div className={`platform-mark mark-${index}`} aria-label={name}>{index===0?<span>f</span>:index===1?<span>G</span>:index===2?<span>♪</span>:index===3?<span>◔</span>:index===4?<span>in</span>:<span>◎</span>}</div>}

function UtmPage({notify}:{notify:(s:string)=>void}){
  const [platform,setPlatform]=useState("Meta"),[values,setValues]=useState({source:"meta",medium:"paid",campaign:"{{campaign.name}}",term:"{{adset.name}}",content:"{{ad.name}}"});
  const presets:Record<string,{source:string;campaign:string;term:string;content:string}>={Meta:{source:"meta",campaign:"{{campaign.name}}",term:"{{adset.name}}",content:"{{ad.name}}"},"Google Ads":{source:"google_ads",campaign:"{campaignid}",term:"{adgroupid}",content:"{creative}"},TikTok:{source:"tiktok",campaign:"__CAMPAIGN_NAME__",term:"__AID_NAME__",content:"__CID_NAME__"},LinkedIn:{source:"linkedin",campaign:"{{CAMPAIGN_NAME}}",term:"{{CAMPAIGN_GROUP_NAME}}",content:"{{CREATIVE_NAME}}"},"ChatGPT Ads":{source:"chatgpt_ads",campaign:"{{campaign_name}}",term:"{{adset_name}}",content:"{{ad_name}}"}};
  const suffix=platform==="Google Ads"?"campaign_id={campaignid}&adgroup_id={adgroupid}&ad_id={creative}":platform==="TikTok"?"campaign_id=__CAMPAIGN_ID__&adgroup_id=__AID__&ad_id=__CID__":platform==="LinkedIn"?"campaign_id={{CAMPAIGN_ID}}&creative_id={{CREATIVE_ID}}":platform==="ChatGPT Ads"?"campaign_id={{campaign_id}}&ad_id={{ad_id}}":"campaign_id={{campaign.id}}&adset_id={{adset.id}}&ad_id={{ad.id}}&campaign_name={{campaign.name}}&adset_name={{adset.name}}&ad_name={{ad.name}}&site_source_name={{site_source_name}}&placement={{placement}}";
  const encodeParameter=(v:string)=>encodeURIComponent(v).replaceAll("%7B","{").replaceAll("%7D","}");
  const url=`utm_source=${encodeParameter(values.source)}&utm_medium=${encodeParameter(values.medium)}&utm_campaign=${encodeParameter(values.campaign)}&utm_term=${encodeParameter(values.term)}&utm_content=${encodeParameter(values.content)}&${suffix}`;
  return <div className="utm-layout"><Card className="utm-builder"><div className="panel-heading"><div><h2>Template UTM</h2><p>Parameter untuk pelacakan campaign per platform.</p></div><Badge className="utm-ready">SIAP DISALIN</Badge></div><div className="platform-pills utm-platforms" role="tablist" aria-label="Platform UTM">{["Meta","Google Ads","TikTok","LinkedIn","ChatGPT Ads"].map(p=><button key={p} role="tab" aria-selected={platform===p} className={platform===p?"selected":""} onClick={()=>{setPlatform(p);setValues(v=>({...v,...presets[p],medium:"paid"}))}}>{p}</button>)}</div><div className="utm-fields">{([ ["source","Source","Nama platform, misalnya meta"],["medium","Medium","Jenis trafik, misalnya paid"],["campaign","Campaign","Nama campaign dari platform"],["term","Ad set / keyword","Nama ad set atau kata kunci"],["content","Ad / creative","Nama iklan atau creative"]] as const).map(([key,label,hint])=><label key={key}>{label}<Input value={values[key]} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}/><small>{hint}</small></label>)}</div><div className="utm-preview-label">PREVIEW PARAMETER</div><div className="utm-preview"><code>{url}</code></div><div className="mapping-actions"><span>Gunakan sebagai URL suffix di Ads Manager.</span><Button onClick={()=>{void navigator.clipboard.writeText(url).then(()=>notify("Parameter UTM disalin."),()=>notify("Clipboard tidak tersedia."))}}><Copy size={15}/> Salin parameter</Button></div></Card><aside className="utm-side"><div className="utm-side-mark"><Filter size={18}/></div><h3>Parameter yang terbaca</h3><p>Nilai UTM disimpan bersama event dan lead untuk membuat campaign report.</p><div className="utm-definitions">{[["utm_source","Kanal asal"],["utm_medium","Jenis trafik"],["utm_campaign","Campaign"],["utm_term","Ad set / keyword"],["utm_content","Ad / creative"]].map(x=><div key={x[0]}><code>{x[0]}</code><span>{x[1]}</span></div>)}</div></aside></div>;
}

function ReportPage({notify}:{notify:(s:string)=>void}){
  const [report,setReport]=useState<any>({rows:[],spend:[]}),[modal,setModal]=useState(false),[busy,setBusy]=useState(false),[from,setFrom]=useState(new Date(Date.now()-29*86400000).toISOString().slice(0,10)),[to,setTo]=useState(new Date().toISOString().slice(0,10));
  const reload=useCallback(()=>api<any>(`/api/report?from=${from}&to=${to}`).then(setReport).catch(e=>notify(e.message)),[from,to,notify]);useEffect(()=>{void reload()},[reload]);
  const costMap=useMemo(()=>new Map<string,number>(report.spend.map((s:any)=>[`${s.platform}:${s.campaign}`,Number(s.spend)] as [string,number])),[report.spend]);const totalSpend=report.spend.reduce((a:number,s:any)=>a+Number(s.spend),0),totalRevenue=report.rows.reduce((a:number,r:any)=>a+Number(r.revenue||0),0),totalLeads=report.rows.reduce((a:number,r:any)=>a+Number(r.leads||0),0);
  const saveCost=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const fd=Object.fromEntries(new FormData(e.currentTarget));try{await api("/api/costs",{method:"POST",body:JSON.stringify(fd)});setModal(false);notify("Biaya campaign tersimpan.");await reload()}catch(err){notify((err as Error).message)}finally{setBusy(false)}};
  const exportCsv=()=>{const csv=[["Platform","Campaign","Spend","Leads","WhatsApp","MQL","Prospek","Closing","Revenue","ROAS"],...report.rows.map((r:any)=>{const spend=Number(costMap.get(`${r.platform}:${r.campaign}`)||0);return[r.platform,r.campaign,spend,r.leads,r.whatsapp,r.mql,r.prospects,r.closing,r.revenue,spend?(Number(r.revenue)/spend).toFixed(2):""]})].map(row=>row.map((v:any)=>`"${String(v??"").replaceAll('"','""')}"`).join(",")).join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"}));a.download="arenka-campaign-report.csv";a.click();URL.revokeObjectURL(a.href)};
  return <><PageHeading eyebrow="REPORTING / CAMPAIGN" title="Campaign report" description="Bandingkan biaya campaign dengan kualitas dan hasil lead." actions={<><Button variant="secondary" onClick={()=>setModal(true)}><CreditCard size={15}/> Biaya manual</Button><Button onClick={exportCsv}><ArrowDownRight size={16}/> Unduh CSV</Button></>}/><div className="report-filters"><label>Dari<Input aria-label="Tanggal mulai" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><span>sampai</span><label>Sampai<Input aria-label="Tanggal akhir" type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><Button variant="secondary" size="sm" onClick={()=>void reload()}>Terapkan</Button><span className="report-period">MATA UANG WORKSPACE · IDR</span></div><div className="report-summary"><div><span>Total spend</span><b>{money(totalSpend)}</b></div><div><span>Leads</span><b>{totalLeads}</b></div><div><span>Revenue closing</span><b>{money(totalRevenue)}</b></div><div><span>ROAS blended</span><b>{totalSpend?`${(totalRevenue/totalSpend).toFixed(2)}×`:"—"}</b></div></div><Card className="table-panel report-table-panel"><div className="panel-heading report-heading"><div><h2>Traffic report</h2><p>{date(from)} — {date(to)}</p></div><span className="report-source-note"><i/> Data event dari tracking code</span></div>{report.rows.length?<div className="table-scroll"><table className="data-table report-table"><thead><tr><th>Platform / campaign</th><th>Spend</th><th>Leads</th><th>WhatsApp</th><th>MQL</th><th>Prospek</th><th>Closing</th><th>Revenue (IDR)</th><th>ROAS</th></tr></thead><tbody>{report.rows.map((r:any,i:number)=>{const spend=Number(costMap.get(`${r.platform}:${r.campaign}`)||0);return <tr key={`${r.platform}-${r.campaign}-${i}`}><td><div className="campaign-cell"><b>{r.platform}</b><small>{r.campaign||"Tanpa nama campaign"}</small></div></td><td>{spend?money(spend):<span className="unavailable">—</span>}</td><td>{r.leads}</td><td>{r.whatsapp}</td><td>{r.mql}</td><td>{r.prospects}</td><td>{r.closing}</td><td>{money(r.revenue)}</td><td>{spend?`${(Number(r.revenue)/spend).toFixed(2)}×`:"—"}</td></tr>})}</tbody></table></div>:<Empty icon={<BarChart3 size={19}/>} title="Belum ada data campaign" text="Lead dan event muncul setelah tracker terpasang. Anda dapat menambahkan biaya manual untuk mulai membandingkan spend." action={<Button size="sm" variant="secondary" onClick={()=>setModal(true)}><Plus size={14}/> Tambah biaya</Button>}/>}<div className="report-footnote">ROAS dihitung dari revenue closing yang tercatat dibagi biaya manual pada rentang tanggal yang dipilih.</div></Card>{modal&&<Dialog title="Catat biaya campaign" onClose={()=>setModal(false)}><form className="dialog-form" onSubmit={saveCost}><label>Platform<Select name="platform" defaultValue="Meta">{platformList.map(p=><option key={p}>{p}</option>)}</Select></label><label>Nama campaign<Input name="campaign" required placeholder="Nama campaign" maxLength={160}/></label><div className="form-row"><label>Biaya (IDR)<Input type="number" name="spend" min="0" max="1000000000000" step="1000" required placeholder="0"/></label><label>Tanggal<Input type="date" name="spend_date" defaultValue={new Date().toISOString().slice(0,10)} required/></label></div><div className="dialog-actions"><Button variant="secondary" type="button" onClick={()=>setModal(false)}>Batal</Button><Button disabled={busy}>{busy?"Menyimpan…":"Simpan biaya"}</Button></div></form></Dialog>}</>;
}

function EventsPage(){const [rows,setRows]=useState<any[]>([]);useEffect(()=>{void api<any[]>("/api/events").then(setRows).catch(()=>setRows([]))},[]);return <><PageHeading eyebrow="TRACKING / EVENT LOGS" title="Event logs" description="Aktivitas yang diterima tracker dari landing page Anda." actions={<Badge className="code-status"><i/> Memantau event</Badge>}/><Card className="table-panel"><div className="table-toolbar"><div><h2 className="toolbar-title">Aktivitas terbaru</h2><p className="toolbar-subtitle">Maksimal 100 event terakhir</p></div><span className="row-count">{rows.length} event</span></div>{rows.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>Event</th><th>Halaman</th><th>Sumber</th><th>Medium</th><th>Campaign</th><th>Waktu</th></tr></thead><tbody>{rows.map(e=><tr key={e.id}><td><Badge className="event-badge">{e.event_name}</Badge></td><td className="url-cell">{e.page_url||"—"}</td><td>{e.source||"Direct"}</td><td>{e.medium||"—"}</td><td>{e.campaign||"—"}</td><td>{date(e.created_at)}</td></tr>)}</tbody></table></div>:<Empty icon={<Activity size={19}/>} title="Belum ada event" text="Pasang script tracking di bagian head website untuk menerima event pertama." action={<Button size="sm" onClick={()=>{history.pushState({},"","/tracking/ads");window.dispatchEvent(new PopStateEvent("popstate"))}}>Lihat tracking code</Button>}/>}</Card></>}

function PlannedModule({title,go}:{title:string;go:(path:string)=>void}){return <><PageHeading eyebrow="ARENKA ADS / TAHAP PENGEMBANGAN" title={title} description="Menu ini sudah dipetakan dari alur produk Dalekta dan akan dibangun bertahap."/><Card className="planned-module"><div className="planned-mark"><Sparkles size={19}/></div><div><h2>Modul belum tersedia</h2><p>Halaman ini belum terhubung ke backend Arenka. Data dan aksi di sini belum aktif. Untuk saat ini, gunakan modul yang sudah berjalan.</p><div className="planned-actions"><Button variant="secondary" onClick={()=>go("/tracking/ads")}>Integrasi iklan</Button><Button onClick={()=>go("/leads")}>Kelola leads</Button></div></div></Card></>}

function LeadLocationsPage({notify}:{notify:(s:string)=>void}){
  const [from,setFrom]=useState(new Date(Date.now()-29*86400000).toISOString().slice(0,10)),[to,setTo]=useState(new Date().toISOString().slice(0,10)),[data,setData]=useState<any>({totals:{},regions:[]}),[busy,setBusy]=useState(false);
  const reload=useCallback(async()=>{setBusy(true);try{setData(await api<any>(`/api/lead-locations?from=${from}&to=${to}`))}catch(e){notify(e instanceof Error?e.message:"Gagal memuat lokasi lead.")}finally{setBusy(false)}},[from,to,notify]);
  useEffect(()=>{void reload()},[reload]);
  const totals=data.totals??{};const exportCsv=()=>{const quote=(v:any)=>String.fromCharCode(34)+String(v??"").replaceAll(String.fromCharCode(34),String.fromCharCode(34).repeat(2))+String.fromCharCode(34);const csv=[["Wilayah","Negara","Visit LP","Klik CTA","Masuk WA","MQL","Prospek","Closing"],...(data.regions??[]).map((r:any)=>[r.region,r.country,r.visits,r.clicks,r.whatsapp,r.mql,r.prospects,r.closing])].map(row=>row.map(quote).join(",")).join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8"}));a.download="arenka-lokasi-leads.csv";a.click();URL.revokeObjectURL(a.href)};
  return <><PageHeading eyebrow="LEADS / LOKASI" title="Lokasi leads" description="Wilayah kunjungan dan interaksi yang tercatat melalui tracking code." actions={<><Button variant="secondary" onClick={exportCsv} disabled={!data.regions?.length}><ArrowDownRight size={15}/> Unduh CSV</Button><Button onClick={()=>void reload()} disabled={busy}>{busy?"Memuat…":"Perbarui data"}</Button></>}/><div className="report-filters"><label>Dari<Input aria-label="Tanggal mulai lokasi" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><span>sampai</span><label>Sampai<Input aria-label="Tanggal akhir lokasi" type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><Button variant="secondary" size="sm" onClick={()=>void reload()} disabled={busy}>Terapkan</Button><span className="report-period">BERDASARKAN LOKASI IP · TANPA MENYIMPAN IP</span></div><div className="location-metrics">{[["Pengunjung",totals.visitors??0],["Visit LP",totals.visits??0],["Klik CTA",totals.clicks??0],["Masuk WA",totals.whatsapp??0],["MQL",totals.mql??0],["Closing",totals.closing??0]].map(([label,value])=><Card key={String(label)} className="location-metric"><span>{label}</span><b>{Number(value).toLocaleString("id-ID")}</b></Card>)}</div><Card className="table-panel location-panel"><div className="panel-heading report-heading"><div><h2>Distribusi berdasarkan wilayah</h2><p>Wilayah disediakan Cloudflare dari perkiraan lokasi koneksi.</p></div><Badge className="code-status"><MapPin size={12}/> Privasi IP</Badge></div>{data.regions?.length?<div className="table-scroll"><table className="data-table location-table"><thead><tr><th>Wilayah</th><th>Negara</th><th>Visit LP</th><th>Klik CTA</th><th>Masuk WA</th><th>MQL</th><th>Prospek</th><th>Closing</th></tr></thead><tbody>{data.regions.map((r:any)=><tr key={`${r.country}-${r.region}`}><td><b>{r.region}</b></td><td>{r.country||"—"}</td><td>{r.visits||0}</td><td>{r.clicks||0}</td><td>{r.whatsapp||0}</td><td>{r.mql||0}</td><td>{r.prospects||0}</td><td>{r.closing||0}</td></tr>)}</tbody></table></div>:<Empty icon={<MapPin size={19}/>} title="Belum ada data lokasi" text="Lokasi mulai dihitung untuk event baru setelah migrasi database dan tracker terbaru aktif. IP mentah tidak disimpan."/>}</Card></>;
}

